    -- Framework
    do
        function Menu.Draw(Type : String, Properties : Table, Table : Table)
            local Render = NewInstance(Type)

            if Type == "Frame" then
                Render.BorderSizePixel = 1
                Render.BackgroundTransparency = 0
                Render.BorderColor3 = NewRGB(0, 0, 0)
                Render.BackgroundColor3 = NewRGB(0, 0, 0)
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "ViewportFrame" then
                Render.BorderSizePixel = 1
                Render.BackgroundTransparency = 0
                Render.BorderColor3 = NewRGB(0, 0, 0)
                Render.BackgroundColor3 = NewRGB(0, 0, 0)
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "UIStroke" then
                Render.LineJoinMode = Enum.LineJoinMode.Miter
                Render.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual
                Render.Color = NewRGB(0, 0, 0)
                Render.Transparency = 0
                Render.Thickness = 1
            elseif Type == "TextLabel" then
                Render.BackgroundTransparency = 1
                Render.TextStrokeTransparency = 1
                Render.TextTransparency = 0
                Render.BorderSizePixel = 0
                Render.Text = "text"
                Render.TextStrokeColor3 = NewRGB(0, 0, 0)
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "TextButton" then
                Render.BorderSizePixel = 1
                Render.BackgroundTransparency = 0
                Render.TextStrokeTransparency = 1
                Render.BorderColor3 = NewRGB(0, 0, 0)
                Render.BackgroundColor3 = NewRGB(50, 50, 50)
                Render.TextStrokeColor3 = NewRGB(0, 0, 0)
                Render.AutoButtonColor = false
                Render.RichText = true
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "ImageButton" then
                Render.BorderSizePixel = 1
                Render.BackgroundTransparency = 0
                Render.ImageColor3 = NewRGB(255, 255, 255)
                Render.BorderColor3 = NewRGB(0, 0, 0)
                Render.BackgroundColor3 = NewRGB(50, 50, 50)
                Render.ResampleMode = "Default"
                Render.AutoButtonColor = false
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "ImageLabel" then
                Render.BorderSizePixel = 1
                Render.BackgroundTransparency = 0
                Render.ImageColor3 = NewRGB(255, 255, 255)
                Render.BorderColor3 = NewRGB(0, 0, 0)
                Render.BackgroundColor3 = NewRGB(50, 50, 50)
                Render.ResampleMode = "Default"
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "ScrollingFrame" then
                Render.BorderSizePixel = 1
                Render.BackgroundTransparency = 1
                Render.BorderColor3 = NewRGB(0, 0, 0)
                Render.BackgroundColor3 = NewRGB(0, 0, 0)
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "TextBox" then
                Render.ClearTextOnFocus = false
                Render.PlaceholderText = "Placeholder"
                Render.TextStrokeColor3 = NewRGB(0, 0, 0)
                Render.TextStrokeTransparency = 1
                Render.BorderSizePixel = 1
                Render.BackgroundTransparency = 1
                Render.BorderColor3 = NewRGB(0, 0, 0)
                Render.BackgroundColor3 = NewRGB(0, 0, 0)
                Render.ZIndex = Menu.CurrentZIndex
                Render.Visible = true
            elseif Type == "ScreenGui" then
                Render.DisplayOrder = 10
                Render.ZIndexBehavior = Enum.ZIndexBehavior.Global
            elseif Type == "UIDragDetector" then
                Render.CursorIcon = "rbxasset://SystemCursors/Arrow"
                Render.ActivatedCursorIcon = "rbxasset://SystemCursors/Arrow"
            end

            if Type ~= "UIStroke" and Properties["TextStrokeTransparency"] ~= nil then
                Menu.Draw("UIStroke", {
                    Parent = Render,
                    Color = Properties.TextStrokeColor3,
                    LineJoinMode = Properties.LineJoinMode,
                    ApplyStrokeMode = Properties.ApplyStrokeMode,
                    Thickness = Properties.Thickness,
                    Transparency = Properties.TextStrokeTransparency
                })
            end

            if StringFind(Lower(Type), "text") then
                local Font = Properties.FontFace or Fonts["Verdana Bold"]

                Render["FontFace"] = Font[1]
                Render["TextSize"] = Font[2]
                Render["TextColor3"] = Font[3]
            end

            for Index, Value in next, Properties do
                if Index == "FontFace" or Index == "TextStrokeTransparency" then continue end

                Render[Index] = Value
            end

            if typeof(Table) == "table" then
                Table[#Table + 1] = Render
            end

            Menu.CurrentZIndex += 1
            Menu.Renders[#Menu.Renders + 1] = Render

            return Render
        end

        function Menu.Remove(Object : Instance)
            local Renders = Menu.Renders
            local Descendants = Menu.GetDescendants(Object)

            for i = 1, #Descendants do
                Remove(Renders, Find(Renders, Descendants[i]))
            end

            Destroy(Object)
        end

        function Menu.GetDescendants(Object : Instance)
            return { Object, Unpack(GetDescendants(Object)) }
        end

        function Menu.Tween(Object : Instance, Info : TweenInfo, Properties : Table)
            local Tween = TweenService:Create(Object, Info, Properties)

            Tween:Play()

            return Tween
        end

        function Menu.Error(Message : String)
            error(Message)
        end

        function Menu.Config(Action : String, Method : String)
            if Action == "New" then
                return WriteFile(Format("%s/%s.cfg", Menu.Folders.Configs, Method), Menu.Config("Get"))
            elseif Action == "Get" then
                local List = {}

                for Section, Values in next, Flags do
                    if typeof(Values.Get) == "function" then
                        List[Section] = Values.Get()
                    else
                        List[Section] = {}

                        for Name, Value in next, Values do
                            if typeof(Value) == "table" and typeof(Value.Get) == "function" then
                                List[Section][Name] = Value.Get()
                            end
                        end
                    end
                end

                return JSONEncode(HttpService, List)
            elseif Action == "Load" then
                local Path = Format("%s/%s.cfg", Menu.Folders.Configs, Method)

                local Config = JSONDecode(HttpService, IsFile(Path) and ReadFile(Path) or Method)

                for Section, Values in next, Config do
                    local Category = Flags[Section]

                    if Category then
                        if typeof(Category.Set) == "function" then
                            Category.Set(Values)
                        else
                            for Name, Value in next, Values do
                                local Flag = Category[Name]

                                if Flag then
                                    Flag.Set(Value)
                                end
                            end
                        end
                    end
                end

                return Config
            elseif Action == "Save" then
                local Path = Format("%s/%s.cfg", Menu.Folders.Configs, Method)

                if IsFile(Path) then
                    return WriteFile(Path, Menu.Config("Get"))
                end
            elseif Action == "Reset" then
                local Path = Format("%s/%s.cfg", Menu.Folders.Configs, Method)

                if IsFile(Path) then
                    return WriteFile(Path, "{}")
                end
            elseif Action == "Delete" then
                local Path = Format("%s/%s.cfg", Menu.Folders.Configs, Method)

                if IsFile(Path) then
                    return DelFile(Path)
                end
            elseif Action == "List" then
                local List = {}
                local Configs = ListFiles(Menu.Folders.Configs)

                for i = 1, #Configs do
                    List[#List + 1] = Match(Configs[i], "([^/\\]+)%.cfg$")
                end

                return List
            end
        end

        function Menu.Script(Action : String, Name : String)
            if Action == "List" then
                local List = {}
                local Scripts = ListFiles(Menu.Folders.Scripts)

                for i = 1, #Scripts do
                    List[#List + 1] = Match(Scripts[i], "([^/\\]+).lua")
                end

                return List
            elseif Action == "Load" then
                local Path = Format("%s/%s.lua", Menu.Folders.Scripts, Name)

                if IsFile(Path) then
                    Menu.Script("Unload", Name)

                    local Module = LoadFile(Path)()
                    Module.Load({ ["Menu"] = Menu })

                    Menu.LoadedScripts[Name] = Module
                end
            elseif Action == "Unload" then
                local Module = Menu.LoadedScripts[Name]

                if Module then
                    Module.Unload()
                    Module = nil
                end
            end
        end

        function Menu.Unload(Fade : Boolean)
            local Library = Menu.Library
            local Windows = Library.Windows

            for i = 1, #Windows do
                local Window = Windows[i]
                local Watermark = Window.Watermark

                if Window then
                    Wrap(function()
                        if Fade and Window.IsVisible and not Window.IsFading then
                            Library:Fade(Window, false)

                            Wait(0.25)
                        end

                        Menu.Remove(Window.Outline)
                        Menu.Remove(Window["Notifcations Holder"])
                    end)()
                end

                if Watermark then
                    Wrap(function()
                        if Fade and Watermark.IsVisible and not Watermark.IsFading then
                            Watermark.Fade(false)

                            Wait(0.25)
                        end

                        Menu.Remove(Watermark.Frame)
                    end)()
                end
            end

            Delay(0.25, function()
                for i = 1, #Connections do
                    local Connection = Connections[i]

                    if Connection then
                        Connection:Disconnect()
                    end
                end

                Clear(Connections)
                Clear(Menu.Renders)
            end)
        end
    end


    -- Folders
    do
        if not IsFolder(BasePath) then
            MakeFolder(BasePath)
        end

        for _, Path in next, Menu.Folders do
            if not IsFolder(Path) then
                MakeFolder(Path)
            end
        end
    end


    -- Theme
    do
        Theme = {
            ["Black"] = NewRGB(0, 0, 0),
            ["White"] = NewRGB(255, 255, 255),

            ["Outline"] = NewRGB(9, 9, 9),
            ["Inline"] = NewRGB(36, 36, 36),

            ["Contrast"] = {
                ["A"] = NewRGB(23, 23, 23),
                ["B"] = NewRGB(28, 28, 28)
            },

            ["Text Color"] = {
                ["A"] = NewRGB(218, 218, 218),
                ["B"] = NewRGB(122, 122, 122)
            },

            ["Divider"] = NewRGB(55, 55, 55),

            ["Accent"] = NewRGB(207, 155, 166)
        }

        Menu.Theme = Theme
    end


    -- Fonts
    do
        function Menu.ImportFont(Name : String, Data : String, WeightNumber : Number, WeightEnum : Enum, StyleEnum : Enum)
            WeightNumber = WeightNumber or 400
            WeightEnum = WeightEnum or Enum.FontWeight.Regular
            StyleEnum = StyleEnum or Enum.FontStyle.Normal

            local Path = Menu.Folders.Fonts .. "/"

            local File1Path = Format("%s%s.ttf", Path, Name)
            local File2Path = Format("%s%s.font", Path, Name)

            WriteFile(File1Path, Decode(Data))

            WriteFile(File2Path, JSONEncode(HttpService, {
                name = Name,
                faces = {
                    {
                        name = "Regular",
                        weight = WeightNumber,
                        style = "normal",
                        assetId = GetCustomAsset(File1Path)
                    }
                }
            }))

            return NewFont(GetCustomAsset(File2Path), WeightEnum, StyleEnum)
        end

        function Menu.GetTextBounds(Text : String, FontFace : Table)
            local Params = NewInstance("GetTextBoundsParams")

            Params.Text = Text
            Params.Font = FontFace[1]
            Params.Size = FontFace[2]
            Params.Width = ScreenSize.X
            Params.RichText = true

            local Bounds = TextService:GetTextBoundsAsync(Params)

            Destroy(Params)

            return Bounds
        end

        Fonts = {
            ["Verdana Bold"] = {
                [1] = Menu.ImportFont("Verdana Bold", Menu.EncodedAssets["Verdana Bold"], 2000, Enum.FontWeight.Bold),
                [2] = 12,
                [3] = NewRGB(218, 218, 218)
            }
        }

        Menu.Fonts = Fonts
    end


    -- Images
    do
        function Menu.ImportImage(Name : String, Data : String)
            local ImagePath = Format("%s/%s.png", Menu.Folders.Images, Name)

            WriteFile(ImagePath, Decode(Data))

            return GetCustomAsset(ImagePath)
        end

        for Index, Data in next, EncodedAssets do
            if Fonts[Index] then continue end

            Images[Index] = Menu.ImportImage(Index, Data)
        end

        Menu.Images = Images
    end


    -- Init
    do
        Menu["Overlay"] = Menu.Draw("ScreenGui", { Parent = CoreGui, Name = BasePath, DisplayOrder = 1 })
        Menu["Overlay2"] = Menu.Draw("ScreenGui", { Parent = CoreGui, Name = BasePath, DisplayOrder = 2 })
    end


    -- Library
    do
        local Library = {}; Library.__index = Library
        local Windows = {}; Windows.__index = Windows
        local Tabs = {}; Tabs.__index = Tabs
        local Sections = {}; Sections.__index = Sections
        local Elements = {}; Elements.__index = Elements


        -- Init Library
        do
            Library.Windows = {}
            Library.Colors = {}
            Library.InputBegan = {}
            Library.InputEnded = {}
            Library.InputChanged = {}
            Library.RenderStepped = {}
            Library.PlayerAdded = {}
            Library.PlayerRemoving = {}
        end


        -- Library Functions
        do
            function Library:SetTheme(NewTheme, Indexes, Keys)
                if NewTheme then
                    Menu.Theme = NewTheme
                    Theme = NewTheme
                end

                for Render, Values in next, Library.Colors do
                    if not Render then continue end

                    for i = 1, #Values do
                        local Value = Values[i]

                        local Property = Value[1]
                        local Index = Value[2]
                        local Key = Value[3]

                        local HasKeys = true

                        if Keys then
                            HasKeys = Find(Keys, Key)
                        end

                        if (Indexes == "All") or (Find(Indexes, Index) and HasKeys) then
                            local Color = Theme[Index]

                            local IsTable = typeof(Color) == "table"

                            if IsA(Render, "UIGradient") and Property == "Color" then
                                if IsTable then
                                    local NewData = {}

                                    for k = 1, #Key do
                                        NewData[#NewData + 1] = Color[Key[k]]
                                    end

                                    Render[Property] = NewColorSequence(Unpack(NewData))
                                else
                                    Render[Property] = NewColorSequence(Color)
                                end
                            else
                                if Index == "Glow Size" then
                                    Color = 1 - (Color / 100)
                                end

                                Render[Property] = IsTable and Color[Key] or Color
                            end
                        end
                    end
                end
            end

            function Library:Fade(Self, NewVisible)
                if Self.IsFading then return end

                if Self.CloseContent then
                    Self:CloseContent({ Self.CurrentContent, Self.CurrentColorpicker })
                end

                local Outline = Self.Outline

                Self.IsFading = true
                Outline.Visible = true

                local Descendants = Menu.GetDescendants(Outline)
                local TweenData = NewTweenInfo(0.25, Enum.EasingStyle.Linear)

                Sort(Descendants, function(A, B)
                    return (IsA(A, "GuiObject") and A.ZIndex or 0) > (IsA(B, "GuiObject") and B.ZIndex or 0)
                end)

                for i = 1, #Descendants do
                    Wrap(function()
                        local Descendant = Descendants[i]

                        local Properties = TransparencyProperties[Descendant.ClassName]

                        if Properties then
                            local SelfCache = Self.Cache[Descendant] or {}
                            local TweenProperties = {}

                            for k = 1, #Properties do
                                local Property = Properties[k]

                                local Cached = SelfCache[Property]
                                local Value = Cached or Descendant[Property]

                                if not Cached then
                                    SelfCache[Property] = Value
                                end

                                if Value then
                                    TweenProperties[Property] = NewVisible and Value or 1
                                end
                            end

                            Menu.Tween(Descendant, TweenData, TweenProperties)

                            Self.Cache[Descendant] = SelfCache
                        end
                    end)()
                end

                if NewVisible then
                    Clear(Self.Cache)
                end

                Delay(0.25, function()
                    Self.IsVisible = NewVisible
                    Self.IsFading = false

                    Outline.Visible = NewVisible
                end)
            end

            function Library:Window(Parameters)
                Parameters = Parameters or {}

                local Size = (typeof(Parameters.Size) == "Vector2" and NewUDim2(0, Parameters.Size.X, 0, Parameters.Size.Y)) or (typeof(Parameters.Size) == "UDim2" and Parameters.Size) or NewUDim2(0, 834, 0, 587)
                local Bind = Parameters.Bind or Enum.KeyCode.RightAlt


                local Window = {
                    IsFading = false,
                    IsVisible = false,

                    Cache = {},
                    Tabs = {},

                    Connections = {},
                    Keybinds = {},

                    Key = Bind,
                    Library = Library
                }


                -- Renders
                do
                    local Outline = Menu.Draw("Frame", { Parent = Menu.Overlay, AnchorPoint = NewVector2(0.5, 0.5), Position = NewUDim2(0.5, 0, 0.5, 0), Size = Size, BackgroundColor3 = Theme.Outline, BorderSizePixel = 0, Visible = Window.IsVisible })

                    local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0 })

                    local Header = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 0), Size = NewUDim2(1, -2, 0, 54), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    Menu.Draw("ImageLabel", { Parent = Header, AnchorPoint = NewVector2(0, 0.5), Position = NewUDim2(0, 15, 0.5, 0), Size = NewUDim2(0, 136, 0, 33), BackgroundTransparency = 1, Image = Images.Primordial, BorderSizePixel = 0 })

                    local Accent = Menu.Draw("Frame", { Parent = Header, Position = NewUDim2(0, 0, 1, 0), Size = NewUDim2(1, 0, 0, 1), BackgroundColor3 = Theme.Accent, BorderSizePixel = 0 })

                    local Footer = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 1, -70), Size = NewUDim2(1, -2, 0, 69), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Accent2 = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 1, -70), Size = NewUDim2(1, -2, 0, 1), BackgroundColor3 = Theme.Accent, BorderSizePixel = 0 })

                    local Background = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 55), Size = NewUDim2(1, -2, 1, -125), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0 })

                    local Side = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 55), Size = NewUDim2(0, 165, 1, -125), BackgroundColor3 = Theme.Contrast.B, BorderSizePixel = 0 })

                    local Holder = Menu.Draw("Frame", { Parent = Side, Position = NewUDim2(0, 1, 0, 12), Size = NewUDim2(1, -2, 1, -12), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Border1 = Menu.Draw("Frame", { Parent = Side, Position = NewUDim2(1, 0, 0, 0), Size = NewUDim2(0, 1, 1, 0), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0 })

                    local Border2 = Menu.Draw("Frame", { Parent = Side, Position = NewUDim2(1, 1, 0, 0), Size = NewUDim2(0, 1, 1, 0), BackgroundColor3 = Theme.Outline, BorderSizePixel = 0 })

                    local Shadow = Menu.Draw("Frame", { Parent = Side, Position = NewUDim2(1, 2, 0, 0), Size = NewUDim2(0, 9, 1, 0), BackgroundColor3 = Theme.Black, BorderSizePixel = 0 })

                    local Dragger = Menu.Draw("UIDragDetector", { Parent = Outline })

                    Menu.Draw("UIGradient", { Parent = Shadow, Transparency = NewNumberSequence({ NewNumberKeypoint(0, 0.7, 0), NewNumberKeypoint(1, 1, 0) }) })

                    Menu.Draw("UIListLayout", { Parent = Footer, FillDirection = "Horizontal", HorizontalAlignment = "Center", VerticalAlignment = "Center", Padding = NewUDim(0, 0) })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 13) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 13) })


                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Outline" } }
                        Library.Colors[Inline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Accent] = { { "BackgroundColor3", "Accent" } }
                        Library.Colors[Accent2] = { { "BackgroundColor3", "Accent" } }
                        Library.Colors[Background] = { { "BackgroundColor3", "Contrast", "A" } }
                        Library.Colors[Side] = { { "BackgroundColor3", "Contrast", "B" } }
                        Library.Colors[Border1] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Border2] = { { "BackgroundColor3", "Outline" } }
                    end


                    Window["Outline"] = Outline
                    Window["Background"] = Background

                    Window["Tabs Holder"] = Footer
                    Window["Category Holder"] = Holder

                    Window["Dragger"] = Dragger
                end


                SetMetaTable(Window, Windows)


                -- Input & Connections
                do
                    Library.InputBegan[#Library.InputBegan + 1] = function(Input)
                        if not UserInputService:GetFocusedTextBox() then
                            if Input.KeyCode == Window.Key or Input.UserInputType == Window.Key then
                                Library:Fade(Window, not Window.IsVisible)
                            end
                        end
                    end

                    Connections[#Connections + 1] = Window["Dragger"].DragContinue:Connect(function()
                        local CurrentSection = Window.CurrentSection

                        if CurrentSection then
                            Window:CloseContent({ CurrentSection })
                        end
                    end)
                end


                -- Fading
                do
                    Library:Fade(Window, false)
                    Window.Outline.Visible = false

                    Delay(0.25, function()
                        Library:Fade(Window, true)
                    end)
                end


                Library.Windows[#Library.Windows + 1] = Window

                return Window
            end
        end


        -- Windows Functions
        do
            function Windows:CloseContent(Content)
                local Window = self

                if Content then
                    for i = 1, #Content do
                        local Current = Content[i]

                        if Current then
                            Current.Close()
                        end
                    end
                else
                    local CurrentContent = Window.CurrentContent

                    if CurrentContent then
                        CurrentContent.Close()

                        Window.CurrentContent = nil
                    end
                end
            end

            function Windows:Find(Name)
                local Window = self
                local Tabs = Window.Tabs

                for i = 1, #Tabs do
                    local Tab = Tabs[i]

                    if Tab.Name == Name then
                        return Tab, i
                    end
                end
            end

