                }


                -- Renders
                do
                    local Outline = Menu.Draw("Frame", { Parent = Window["Tabs Holder"], BackgroundColor3 = Theme.White, BorderSizePixel = 0, Size = NewUDim2(0, 75, 0, 50), BackgroundTransparency = 1 })

                    local Button = Menu.Draw("TextButton", { Parent = Outline, BackgroundTransparency = 1, BorderSizePixel = 0, Text = "", Size = NewUDim2(1, 0, 1, 0), Position = EmptyUDim2 })

                    local Image = Menu.Draw("ImageLabel", { Parent = Outline, AnchorPoint = NewVector2(0.5, 0.5), Size = IconSize, Position = IconPosition, Image = Icon, ImageTransparency = 0.585, BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Label = Menu.Draw("TextLabel", { Parent = Outline, AnchorPoint = NewVector2(0.5, 0.5), Position = NewUDim2(0.5, 0, 0.5, 12), Text = Name, BackgroundTransparency = 1, BorderSizePixel = 0, TextColor3 = Theme["Text Color"].B })

                    local CategoryHolder = Menu.Draw("Frame", { Parent = Window["Category Holder"], Position = EmptyUDim2, Size = NewUDim2(1, 0, 1, 0), BackgroundTransparency = 1, Visible = false })

                    local SectionsHolder = Menu.Draw("Frame", { Parent = Window.Background, Position = NewUDim2(0, 169, 0, 12), Size = NewUDim2(1, -171, 1, -14), BackgroundTransparency = 1, Visible = false })

                    local GroupHolder = Menu.Draw("Frame", { Parent = SectionsHolder, Position = EmptyUDim2, Size = NewUDim2(1, -24, 0, 32), BackgroundTransparency = 1 })

                    local Left = Menu.Draw("Frame", { Parent = SectionsHolder, Position = NewUDim2(0, 10, 0, 0), Size = NewUDim2(0.5, -16, 1, -10), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Right = Menu.Draw("Frame", { Parent = SectionsHolder, Position = NewUDim2(0.5, 6, 0, 0), Size = NewUDim2(0.5, -15, 1, -10), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    Menu.Draw("UIListLayout", { Parent = CategoryHolder, FillDirection = "Vertical", HorizontalAlignment = "Left", VerticalAlignment = "Top", Padding = NewUDim(0, 5) })

                    Menu.Draw("UIListLayout", { Parent = Left, Padding = NewUDim(0, 12), FillDirection = "Vertical", HorizontalAlignment = "Left", VerticalAlignment = "Top" })

                    Menu.Draw("UIListLayout", { Parent = Right, Padding = NewUDim(0, 12), FillDirection = "Vertical", HorizontalAlignment = "Left", VerticalAlignment = "Top" })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 10) })

                    Tab["Frame"] = Outline
                    Tab["Button"] = Button

                    Tab["Image"] = Image
                    Tab["Label"] = Label

                    Tab["Category Holder"] = CategoryHolder
                    Tab["Sections Holder"] = SectionsHolder
                    Tab["Groups Holder"] = GroupHolder

                    Tab["Left"] = Left
                    Tab["Right"] = Right
                end


                -- Input & Connections
                do
                    local TabFrame = Tab["Frame"]
                    local TabButton = Tab["Button"]

                    local TabLabel = Tab["Label"]
                    local TabImage = Tab["Image"]

                    local FinalImage = IconPosition - NewUDim2(0, 0, 0, 3)
                    local FinalLabel = NewUDim2(0.5, 0, 0.5, 9)

                    Connections[#Connections + 1] = TabButton.MouseButton1Down:Connect(function()
                        Tab:Open()
                    end)

                    Connections[#Connections + 1] = TabFrame.MouseEnter:Connect(function()
                        if not Tab.IsVisible then
                            Menu.Tween(TabLabel, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].A, Position = FinalLabel })
                            Menu.Tween(TabImage, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageTransparency = 0.3, Position = FinalImage })
                        end
                    end)

                    Connections[#Connections + 1] = TabFrame.MouseLeave:Connect(function()
                        if not Tab.IsVisible then
                            Menu.Tween(TabLabel, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].B, Position = LabelPosition })
                            Menu.Tween(TabImage, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageTransparency = 0.585, Position = IconPosition })
                        end
                    end)
                end


                SetMetaTable(Tab, Tabs)


                if Opened then
                    Tab:Open()
                end


                Window.Tabs[#Window.Tabs + 1] = Tab

                return Tab
            end
        end


        -- Tabs Functions
        do
            function Tabs:Open()
                local Tab = self
                local Window = Tab.Window

                local IsCategory = (Tab.ParentCategory ~= nil)
                local IsGroup = (Tab.ParentGroup ~= nil)
                local CurrentTab = Window.CurrentTab

                if IsCategory then
                    CurrentTab = Tab.ParentCategory.CurrentTab
                elseif IsGroup then
                    CurrentTab = Tab.ParentGroup.CurrentTab
                end

                if CurrentTab == Tab then return end

                Window:CloseContent({ Window.CurrentColorpicker, Window.CurrentContent, Window.CurrentSection })

                if CurrentTab then
                    if not IsCategory then
                        Menu.Tween(CurrentTab.Label, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].B })

                        Library.Colors[Tab.Label] = nil

                        if not IsGroup then
                            Menu.Tween(CurrentTab.Frame, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { BackgroundTransparency = 1 })
                            Menu.Tween(CurrentTab.Image, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageTransparency = 0.585 })

                            CurrentTab["Category Holder"].Visible = false
                        end
                    else
                        Menu.Tween(CurrentTab.Accent, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { BackgroundTransparency = 1 })
                        Menu.Tween(CurrentTab.Shadow, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { BackgroundTransparency = 1 })
                        Menu.Tween(CurrentTab.Label, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].B })
                    end

                    CurrentTab["Sections Holder"].Visible = false
                    CurrentTab.IsVisible = false
                end

                if not IsCategory then
                    if not IsGroup then
                        Menu.Tween(Tab.Frame, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { BackgroundTransparency = 0.96 })
                        Menu.Tween(Tab.Label, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].A, Position = Tab.LabelPosition })
                        Menu.Tween(Tab.Image, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageTransparency = 0.3, Position = Tab.IconPosition })

                        Tab["Category Holder"].Visible = true

                        Window.CurrentTab = Tab
                    else
                        Menu.Tween(Tab.Label, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme.Accent })

                        Library.Colors[Tab.Label] = { { "TextColor3", "Accent" } }

                        Tab.ParentGroup.CurrentTab = Tab
                    end
                else
                    Menu.Tween(Tab.Accent, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { BackgroundTransparency = 0 })
                    Menu.Tween(Tab.Shadow, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { BackgroundTransparency = 0 })
                    Menu.Tween(Tab.Label, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].A })

                    Tab.ParentCategory.CurrentTab = Tab
                end

                Tab["Sections Holder"].Visible = true

                Tab.IsVisible = true
            end

