            function Tabs:Group(Parameters)
                local Tab = self
                local Window = Tab.Window

                Parameters = Parameters or {}


                local Name = Parameters.Name or "Category"
                local Groups = Parameters.Groups or {
                    "Rifles",
                    "Pistols",
                    "SMGs",
