                    local Overlay = Menu.Draw("ImageLabel", { Parent = Frame, Position = NewUDim2(0, 11, 0, 0), Size = NewUDim2(0, 16, 0, 16), BorderSizePixel = 0, BackgroundColor3 = Theme.Accent, Image = Images["Gradient 7"], ImageTransparency = 0.3, Visible = false })

                    local Image = Menu.Draw("ImageLabel", { Parent = Overlay, AnchorPoint = NewVector2(0.5, 0.5), Position = NewUDim2(0.5, 0, 0.5, 0), Size = NewUDim2(0, 12, 0, 9), BorderSizePixel = 0, BackgroundTransparency = 1, Image = Images["Checkmark 3"], ImageColor3 = Theme.Contrast.A })

                    local Button = Menu.Draw("TextButton", { Parent = Frame, Position = NewUDim2(0, -1, 0, -1), Size = NewUDim2(1, 3, 1, 2), BackgroundTransparency = 1, BorderSizePixel = 0, Text = "" })

                    local Label = Menu.Draw("TextLabel", { Parent = Frame, Position = NewUDim2(0, 32, 0, 7), TextColor3 = Unsafe and Theme.Unsafe or Theme["Text Color"].B, BackgroundTransparency = 1, TextXAlignment = "Left", Text = Name })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 4) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 4) })
                    Menu.Draw("UICorner", { Parent = Overlay, CornerRadius = NewUDim(0, 4) })

                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Inline] = { { "BackgroundColor3", "Contrast", "A" } }
                        Library.Colors[Overlay] = { { "BackgroundColor3", "Accent" } }
                        Library.Colors[Image] = { { "ImageColor3", "Contrast", "A" } }
                    end

                    Toggle["Frame"] = Frame

                    Toggle["Inline"] = Inline
                    Toggle["Overlay"] = Overlay

                    Toggle["Button"] = Button
                    Toggle["Label"] = Label
                end


                -- Functions
                do
                    function Toggle.Get()
                        return Toggle.Value
                    end

                    function Toggle.Set(Boolean)
                        if Toggle.Bind and Toggle.Bind.Mode == "Always" and Boolean == false then return end

                        Toggle.Value = Boolean

                        Toggle.Overlay.Visible = Boolean

                        if not Unsafe then
                            Toggle.Label.TextColor3 = Theme["Text Color"][Boolean and "A" or "B"]
                        end

                        Callback(Boolean)
                    end
                end


                -- Input & Connections
                do
                    local ToggleFrame = Toggle["Frame"]
                    local ToggleButton = Toggle["Button"]
                    local ToggleLabel = Toggle["Label"]

                    Connections[#Connections + 1] = ToggleButton.MouseButton1Down:Connect(function()
                        Toggle.Set(not Toggle.Value)
                    end)

                    Connections[#Connections + 1] = ToggleFrame.MouseEnter:Connect(function()
                        if not Toggle.Value then
                            Menu.Tween(ToggleLabel, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].A })
                        end
                    end)

                    Connections[#Connections + 1] = ToggleFrame.MouseLeave:Connect(function()
                        if not Toggle.Value then
                            Menu.Tween(ToggleLabel, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].B })
                        end
                    end)
                end


                Toggle.Set(Default)


                SetMetaTable(Toggle, Elements)


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = Toggle
                        else
                            Flags[Category] = {
                                [Flag] = Toggle
                            }
                        end
                    else
                        Flags[Flag] = Toggle
                    end
                end


                Section.Offset += 24

                return Toggle
            end

            function Sections:Dropdown(Parameters)
                Parameters = Parameters or {}

                local Section = self
                local Window = Section.Window

                local Name = Parameters.Name or ""
                local Options = Parameters.Options or { "General", "Health Bar", "Health Value", "Tool", "Distance" }
                local Default = Parameters.Default
                local Min = Parameters.Min or 1
                local MultiChoice = typeof(Default) == "table"
                local Unsafe = Parameters.Unsafe or false
                local Callback = Parameters.Callback or EmptyFunction
                local Flag = Parameters.Flag
                local Category = Parameters.Category

                local IsNamed = (Name ~= "")


                local Dropdown = {
                    Values = {},
                    IsOpen = false,

                    Value = Default,
                    Options = Options,
                    MultiChoice = MultiChoice,

                    Section = Section,
                    Offset = Section.Offset
                }


                -- Renders
                do
                    local Frame = Menu.Draw("Frame", { Parent = Section.Frame, Position = NewUDim2(0, 0, 0, Section.Offset), Size = NewUDim2(1, 0, 0, 13), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Outline = Menu.Draw("Frame", { Parent = Frame, Position = NewUDim2(0, 10, 0, IsNamed and 15 or 0), Size = NewUDim2(1, -20, 0, 26), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0 })

                    local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0 })

                    local Button = Menu.Draw("TextButton", { Parent = Outline, Size = NewUDim2(1, 0, 1, 0), Position = EmptyUDim2, BackgroundTransparency = 1, Text = "" })

                    local Label = Menu.Draw("TextLabel", { Parent = Inline, AnchorPoint = NewVector2(0, 0.5), Position = NewUDim2(0, 5, 0.5, -1), Size = NewUDim2(1, -25, 1, -4), TextTruncate = "AtEnd", TextXAlignment = "Left", Text = "None selected...", TextColor3 = Theme["Text Color"].B })

                    Menu.Draw("ImageLabel", { Parent = Inline, AnchorPoint = NewVector2(0, 0.5), Position = NewUDim2(1, -18, 0.5, 0), Size = NewUDim2(0, 9, 0, 6), Image = Images["Down Arrow 2"], BorderSizePixel = 0, BackgroundTransparency = 1 })

                    Menu.Draw("TextLabel", { Parent = Frame, Position = NewUDim2(0, 10, 0, 5), Text = Name, TextXAlignment = "Left", TextColor3 = Unsafe and Theme.Unsafe or Theme["Text Color"].A })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 5) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 5) })

                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Inline] = { { "BackgroundColor3", "Contrast", "A" } }
                    end

                    Dropdown["Frame"] = Frame
                    Dropdown["Outer"] = Outline

                    Dropdown["Button"] = Button
                    Dropdown["Label"] = Label
                end


                -- Functions
                do
                    function Dropdown.Get()
                        return Dropdown.Value
                    end

                    function Dropdown.Set(Value)
                        if typeof(Value) == "table" then
                            for i = #Value, 1, -1 do
                                if not Find(Dropdown.Options, Value[i]) then
                                    Remove(Value, i)
                                end
                            end

                            Dropdown.Value = MultiChoice and Value or Value[1]
                        elseif not Find(Dropdown.Options, Value) then
                            return
                        end

                        Dropdown.Update()

                        Callback(Value)
                    end

                    function Dropdown.Update()
                        Dropdown.Label.Text = MultiChoice and (#Dropdown.Value > 0 and Concat(Dropdown.Value, ", ") or "None selected...") or (Dropdown.Value and Dropdown.Value) or "None selected..."
                    end

                    function Dropdown.Refresh(Value)
                        local DropdownValue = Dropdown.Value
                        local DropdownValues = Dropdown.Values
                        local DropdownOptions = Dropdown.Options

                        if MultiChoice then
                            local Amount = #DropdownValue
                            local Found = Find(DropdownValue, Value)

                            if Found then
                                if Amount > Min then
                                    Remove(Dropdown.Value, Found)
                                end
                            else
                                Dropdown.Value[Amount + 1] = Value
                            end
                        else
                            if DropdownValue == Value then
                                if Min < 1 then
                                    Dropdown.Value = nil
                                end
                            else
                                Dropdown.Value = Value
                            end
                        end

                        DropdownValue = Dropdown.Value

                        for i = 1, #DropdownOptions do
                            local Option = Dropdown.Options[i]
                            local Frame = DropdownValues[i]

                            local IsValue = (MultiChoice and Find(DropdownValue, Option)) or (DropdownValue == Option)

                            Frame.TextColor3 = Theme["Text Color"][IsValue and "A" or "B"]
                        end

                        Dropdown.Update()

                        Callback(DropdownValue)
                    end

                    function Dropdown.Open()
                        if Dropdown.IsOpen then
                            Dropdown.Close()
                            return
                        end

                        Window:CloseContent()
                        Window.CurrentContent = Dropdown

                        Dropdown.IsOpen = true


                        -- Renders
                        do
                            local Outline = Menu.Draw("Frame", { Parent = Dropdown.Outer, Position = NewUDim2(0, 0, 1, 2), Size = NewUDim2(1, 1, 0, 0), BackgroundColor3 = Theme.Inline, BackgroundTransparency = 1, BorderSizePixel = 0 })

                            local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0, ClipsDescendants = true })

                            Menu.Draw("UIListLayout", { Parent = Inline, Padding = NewUDim(0, 1), FillDirection = "Vertical", VerticalFlex = "Fill", ItemLineAlignment = "Center" })

                            Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 5) })
                            Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 5) })

                            -- Colors
                            do
                                Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                                Library.Colors[Inline] = { { "BackgroundColor3", "Contrast", "A" } }
                            end

                            Dropdown["Outline"] = Outline
                            Dropdown["Inline"] = Inline
                        end


                        -- Input & Connections
                        do
                            local Outline = Dropdown.Outline
                            local Inline = Dropdown.Inline

                            Connections[#Connections + 1] = Outline:GetPropertyChangedSignal("BackgroundTransparency"):Connect(function()
                                Inline.BackgroundTransparency = Outline.BackgroundTransparency
                            end)
                        end


                        -- Options
                        do
                            local Inline = Dropdown.Inline
                            local DropdownOptions = Dropdown.Options

                            for i = 1, #DropdownOptions do
                                local Option = DropdownOptions[i]


                                local IsValue = (MultiChoice and Find(Dropdown.Value, Option)) or (Dropdown.Value == Option)

                                local Button = Menu.Draw("TextButton", { Parent = Inline, ZIndex = Inline.ZIndex + 1, Position = EmptyUDim2, Size = NewUDim2(1, 0, 0, 0), BorderSizePixel = 0, Text = "", BackgroundTransparency = 1, AutomaticSize = "Y" })

                                local Value = Menu.Draw("TextLabel", { Parent = Button, ZIndex = Button.ZIndex + 1, AnchorPoint = NewVector2(0, 0.5), Position = NewUDim2(0, 5, 0.5, 0), Size = NewUDim2(1, -25, 1, 0), TextTruncate = "AtEnd", TextXAlignment = "Left", Text = Option, BackgroundTransparency = 1, TextTransparency = 1, TextColor3 = Theme["Text Color"][IsValue and "A" or "B"] })


                                -- Input & Connections
                                do
                                    Connections[#Connections + 1] = Button.MouseButton1Down:Connect(function()
                                        Dropdown.Refresh(Option)
                                    end)

                                    Connections[#Connections + 1] = Button.MouseEnter:Connect(function()
                                        local IsValue = (MultiChoice and Find(Dropdown.Value, Option)) or (Dropdown.Value == Option)

                                        if not IsValue then
                                            Menu.Tween(Value, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].A })
                                        end
                                    end)

                                    Connections[#Connections + 1] = Button.MouseLeave:Connect(function()
                                        local IsValue = (MultiChoice and Find(Dropdown.Value, Option)) or (Dropdown.Value == Option)

                                        if not IsValue then
                                            Menu.Tween(Value, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { TextColor3 = Theme["Text Color"].B })
                                        end
                                    end)
                                end


                                Dropdown.Values[#Dropdown.Values + 1] = Value
                            end
                        end


                        -- Animations
                        do
                            local Descendants = Menu.GetDescendants(Dropdown.Outline)

                            for i = 1, #Descendants do
                                local Descendant = Descendants[i]

                                if
                                    IsA(Descendant, "UIGradient") or
                                    IsA(Descendant, "TextButton") or
                                    IsA(Descendant, "UIListLayout") or
                                    IsA(Descendant, "UICorner") or
                                    Descendant == Dropdown.Inline
                                then
                                    continue
                                end

                                local Properties = { BackgroundTransparency = 0 }

                                if IsA(Descendant, "TextLabel") then
                                    Properties = { TextTransparency = 0 }
                                elseif Descendant == Dropdown.Outline then
                                    Properties["Size"] = NewUDim2(0, Descendant.AbsoluteSize.X, 0, (18 * #Dropdown.Options))
                                elseif IsA(Descendant, "UIStroke") then
                                    Properties = { Transparency = 0 }
                                end

                                Menu.Tween(Descendant, NewTweenInfo(0.08, Enum.EasingStyle.Linear), Properties)
                            end
                        end


                        Dropdown.OpenFrame = Dropdown.Outline
                    end

                    function Dropdown.Close()
                        if not Dropdown.IsOpen then return end

                        Window.CurrentContent = nil
                        Dropdown.IsOpen = false


                        -- Animations
                        do
                            local Descendants = Menu.GetDescendants(Dropdown.Outline)

                            for i = 1, #Descendants do
                                local Descendant = Descendants[i]

                                if
                                    IsA(Descendant, "UIGradient") or
                                    IsA(Descendant, "TextButton") or
                                    IsA(Descendant, "UIListLayout") or
                                    IsA(Descendant, "UICorner") or
                                    Descendant == Dropdown.Inline
                                then
                                    continue
                                end

                                local Properties = { BackgroundTransparency = 1 }

                                if IsA(Descendant, "TextLabel") then
                                    Properties = { TextTransparency = 1 }
                                elseif IsA(Descendant, "UIStroke") then
                                    Properties = { Transparency = 1 }
                                elseif Descendant == Dropdown.Outline then
                                    Properties["Size"] = NewUDim2(0, Descendant.AbsoluteSize.X, 0, 0)
                                end

                                Menu.Tween(Descendant, NewTweenInfo(0.08, Enum.EasingStyle.Linear), Properties)
                            end
                        end


                        Delay(0.08, function()
                            Clear(Dropdown.Values)

                            Menu.Remove(Dropdown.OpenFrame)
                        end)
                    end
                end


                Dropdown.Update()


                -- Inputs & Connections
                do
                    local DropdownButton = Dropdown["Button"]

                    Connections[#Connections + 1] = DropdownButton.MouseButton1Down:Connect(Dropdown.Open)
                end


                SetMetaTable(Dropdown, Elements)


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = Dropdown
                        else
                            Flags[Category] = {
                                [Flag] = Dropdown
                            }
                        end
                    else
                        Flags[Flag] = Dropdown
                    end
                end


                Section.Offset += (IsNamed and 49 or 34)

                return Dropdown
            end

            function Sections:Slider(Parameters)
                Parameters = Parameters or {}

                local Section = self

                local Name = Parameters.Name or ""
                local Min = Parameters.Min or 0
                local Max = Parameters.Max or 100
                local Default = Parameters.Default or 50
                local Prefix = Parameters.Prefix or ""
                local Decimals = Parameters.Decimals or 1
                local Callback = Parameters.Callback or EmptyFunction
                local Specials = Parameters.Specials or false
                local Unsafe = Parameters.Unsafe or false
                local Flag = Parameters.Flag
                local Category = Parameters.Category

                local IsNamed = (Name ~= "")

                local Cut = Split(Decimals, ".")[2]
                local DecimalSuffix = Cut and #Cut or 0

                Default = Clamp(Default, Min, Max)
                Decimals = 1 / Decimals


                local Slider = {
                    Decimals = Decimals,

                    Prefix = Prefix,
                    Value = 0,

                    Min = Min,
                    Max = Max,

                    Section = Section,
                    Offset = Section.Offset
                }


                -- Renders
                do
                    local Frame = Menu.Draw("Frame", { Parent = Section.Frame, Position = NewUDim2(0, 0, 0, Section.Offset), Size = NewUDim2(1, 0, 0, 13), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Outline = Menu.Draw("Frame", { Parent = Frame, Position = NewUDim2(0, 10, 0, 19), Size = NewUDim2(1, -20, 0, 12), BorderSizePixel = 0, BackgroundColor3 = Theme.Inline })

                    local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BorderSizePixel = 0, BackgroundColor3 = Theme.Contrast.A })

                    local Button = Menu.Draw("ImageButton", { Parent = Inline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Button2 = Menu.Draw("ImageButton", { Parent = Button, Position = EmptyUDim2, Size = NewUDim2((Slider.Value - Slider.Min) / (Slider.Max - Slider.Min), 0, 1, 0), BackgroundColor3 = Theme.Accent, BorderSizePixel = 0, Interactable = false, Image = Images.Gradient, ImageTransparency = 0.3 })

                    local BoxOutline = Menu.Draw("Frame", { Parent = Frame, Position = NewUDim2(0, IsNamed and 16 + Menu.GetTextBounds(Name, Fonts["Verdana Bold"]).X or 11, 0, -1), Size = NewUDim2(0, 36, 0, 17), BorderSizePixel = 0, BackgroundColor3 = Theme.Inline })

                    local BoxInline = Menu.Draw("Frame", { Parent = BoxOutline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BorderSizePixel = 0, BackgroundColor3 = Theme.Contrast.A })

                    local TextBox = Menu.Draw("TextBox", { Parent = BoxInline, Position = NewUDim2(0, 0, 0, 0), Size = NewUDim2(1, 0, 1, -1), BorderSizePixel = 0, BackgroundTransparency = 1, TextColor3 = Theme["Text Color"].B, TextSize = 11, PlaceholderText = "", ClipsDescendants = true })

                    local DraggerOutline = Menu.Draw("Frame", { Parent = Button2, AnchorPoint = NewVector2(0, 0.5), Position = NewUDim2(1, -2, 0.5, 0), Size = NewUDim2(0, 6, 0, 12), BorderSizePixel = 0, BackgroundColor3 = NewRGB(111, 109, 109) })

                    local DraggerInline = Menu.Draw("Frame", { Parent = DraggerOutline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BorderSizePixel = 0, BackgroundColor3 = NewRGB(161, 161, 161) })

                    Menu.Draw("TextLabel", { Parent = Frame, Position = NewUDim2(0, 11, 0, 7), Text = Name, TextXAlignment = "Left", TextColor3 = Unsafe and Theme.Unsafe or Theme["Text Color"].A })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 5) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 5) })
                    Menu.Draw("UICorner", { Parent = Button2, CornerRadius = NewUDim(0, 5) })
                    Menu.Draw("UICorner", { Parent = BoxOutline, CornerRadius = NewUDim(0, 6) })
                    Menu.Draw("UICorner", { Parent = BoxInline, CornerRadius = NewUDim(0, 6) })
                    Menu.Draw("UICorner", { Parent = DraggerOutline, CornerRadius = NewUDim(0, 5) })
                    Menu.Draw("UICorner", { Parent = DraggerInline, CornerRadius = NewUDim(0, 5) })

                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Inline] = { { "BackgroundColor3", "Contrast", "A" } }
                        Library.Colors[Button2] = { { "BackgroundColor3", "Accent" } }
                        Library.Colors[BoxOutline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[BoxInline] = { { "BackgroundColor3", "Contrast", "A" } }
                    end

                    Slider["Frame"] = Frame
                    Slider["Outline"] = Outline

                    Slider["Button"] = Button
                    Slider["Button2"] = Button2

                    Slider["Label"] = TextBox
                    Slider["Box"] = BoxOutline
                end


                -- Functions
                do
                    local Button = Slider["Button2"]
                    local Label = Slider["Label"]
                    local Box = Slider["Box"]

                    function Slider.Get()
                        return Slider.Value
                    end

                    function Slider.Set(Value)
                        Slider.Value = Clamp(Round(Value * Slider.Decimals) / Slider.Decimals, Slider.Min, Slider.Max)

                        local NewValue = Slider.Value

                        local Special = false

                        if Specials and NewValue == Specials[2] then
                            Special = Specials[1]
                        end

                        local NewText = Special or Format(`%.{DecimalSuffix}f%s`, NewValue, Prefix)

                        Menu.Tween(Button, NewTweenInfo(0.1, Enum.EasingStyle.Linear), { Size = NewUDim2(((NewValue - Slider.Min) / (Slider.Max - Slider.Min)), 0, 1, 0) })

                        Label.Text = NewText

                        Box.Size = NewUDim2(0, Menu.GetTextBounds(NewText, Fonts["Verdana Bold"]).X + 9, 0, 17)

                        Callback(Slider.Value)
                    end

                    function Slider.Refresh()
                        local AbsoluteX = Slider.Button.AbsoluteSize.X

                        local SliderMin = Slider.Min
                        local SliderMax = Slider.Max

                        Slider.Set(Clamp(SliderMin + (SliderMax - SliderMin) * (Clamp(Mouse.X - Button.AbsolutePosition.X, 0, AbsoluteX) / AbsoluteX), SliderMin, SliderMax))

                        RenderStepped:Wait()
                    end
                end


                Slider.Set(Default)


                -- Inputs & Connections
                do
                    local SliderButton = Slider["Button"]
                    local SliderBox = Slider["Label"]

                    local MouseDown = false

                    Connections[#Connections + 1] = SliderButton.MouseButton1Down:Connect(function()
                        Slider.Refresh()

                        MouseDown = true
                    end)

                    Connections[#Connections + 1] = SliderBox.FocusLost:Connect(function(Submited)
                        if not Submited then
                            SliderBox.Text = Slider.Value
                        end

                        local String = SliderBox.Text
                        local Number = String == "" and 0 or tonumber(String)

                        Slider.Set(Number or Slider.Value)
                    end)

                    Library.InputEnded[#Library.InputEnded + 1] = function(Input)
                        if Input.UserInputType == Enum.UserInputType.MouseButton1 and MouseDown then
                            MouseDown = false

                            Slider.Refresh()
                        end
                    end

                    Library.InputChanged[#Library.InputChanged + 1] = function(Input)
                        if Input.UserInputType == Enum.UserInputType.MouseMovement and MouseDown then
                            Slider.Refresh()
                        end
                    end
                end


                SetMetaTable(Slider, Elements)


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = Slider
                        else
                            Flags[Category] = {
                                [Flag] = Slider
                            }
                        end
                    else
                        Flags[Flag] = Slider
                    end
                end


                Section.Offset += 40

                return Slider
            end

            function Sections:Button(Parameters)
                Parameters = Parameters or {}

                local Section = self

                local Name = Parameters.Name or "Load"
                local Confirm = Parameters.Confirm or false
                local PassedCallback = Parameters.Callback or EmptyFunction
                local CallbackText = Parameters.CallbackText
                local Flag = Parameters.Flag
                local Category = Parameters.Category


                local Button = {
                    Confirmable = false,

                    Section = Section,
                    Offset = Section.Offset
                }


                local Callback = function(...)
                    if typeof(CallbackText) == "string" then
                        Button.Button.Text = CallbackText
                    end

                    Button.Button.TextColor3 = Theme["Text Color"].A

                    Delay(0.25, function()
                        Button.Button.Text = Name

                        Button.Button.TextColor3 = Theme["Text Color"].B
                    end)

                    PassedCallback(...)
                end


                -- Renders
                do
                    local Frame = Menu.Draw("Frame", { Parent = Section.Frame, Position = NewUDim2(0, 0, 0, Section.Offset), Size = NewUDim2(1, 0, 0, 13), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Outline = Menu.Draw("Frame", { Parent = Frame, Position = NewUDim2(0, 10, 0, 0), Size = NewUDim2(1, -20, 0, 26), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0 })

                    local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0 })

                    local TextButton = Menu.Draw("TextButton", { Parent = Outline, Size = NewUDim2(1, 0, 1, -1), Position = EmptyUDim2, BackgroundTransparency = 1, Text = Name, TextColor3 = Theme["Text Color"].B })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 5) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 5) })

                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Inline] = { { "BackgroundColor3", "Contrast", "A" } }
                    end

                    Button["Frame"] = Outline
                    Button["Button"] = TextButton
                end


                -- Functions
                do
                    function Button.Set() end
                    function Button.Get() end

                    function Button.Activate()
                        if Confirm then
                            if Button.Confirmable then
                                Callback()

                                Cancel(Button.Task)

                                Button.Confirmable = false
                                Button.Button.TextColor3 = Theme["Text Color"].B
                                Button.Button.Text = Name
                            else
                                Button.Task = Spawn(function()
                                    for i = 3.00, 0, -0.1 do
                                        Button.Button.Text = Format("Confirm? [%.1f]", i)
                                        Button.Button.TextColor3 = Theme["Text Color"].A

                                        Button.Confirmable = true
                                        Wait(0.1)
                                    end

                                    Button.Confirmable = false
                                    Button.Button.TextColor3 = Theme["Text Color"].B
                                    Button.Button.Text = Name
                                end)
                            end
                        else
                            Callback()
                        end
                    end
                end


                -- Input & Connections
                do
                    Connections[#Connections + 1] = Button["Button"].MouseButton1Down:Connect(Button.Activate)
                end


                SetMetaTable(Button, Elements)


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = Button
                        else
                            Flags[Category] = {
                                [Flag] = Button
                            }
                        end
                    else
                        Flags[Flag] = Button
                    end
                end


                Section.Offset += 34

                return Button
            end

            function Sections:TextBox(Parameters)
                Parameters = Parameters or {}

                local Section = self

                local PlaceholderText = Parameters.Placeholder or "Enter Text..."
                local Default = (Parameters.Default and Parameters.Default) or (Parameters.Placeholder and PlaceholderText) or ""
                local ResetText = Parameters.ResetText or Default
                local Callback = Parameters.Callback or EmptyFunction
                local ClearText = Parameters.ResetOnSubmit or false
                local RequireSubmit = Parameters.RequireSubmit or false
                local Flag = Parameters.Flag
                local Category = Parameters.Category


                local TextBox = {
                    OldValue = Default,
                    Value = Default,

                    Section = Section,
                    Offset = Section.Offset
                }


                -- Renders
                do
                    local Frame = Menu.Draw("Frame", { Parent = Section.Frame, Position = NewUDim2(0, 0, 0, Section.Offset), Size = NewUDim2(1, 0, 0, 13), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Outline = Menu.Draw("Frame", { Parent = Frame, Position = NewUDim2(0, 10, 0, 0), Size = NewUDim2(1, -20, 0, 26), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0 })

                    local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0 })

                    local Box = Menu.Draw("TextBox", { Parent = Inline, Position = NewUDim2(0, 5, 0, 0), Size = NewUDim2(1, -5, 1, 0), BackgroundTransparency = 1, BorderSizePixel = 0, PlaceholderText = PlaceholderText, Text = Default, ClipsDescendants = true, TextColor3 = Theme["Text Color"].A, PlaceholderColor3 = Theme["Text Color"].B, TextXAlignment = "Left" })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 5) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 5) })

                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Inline] = { { "BackgroundColor3", "Contrast", "A" } }
                    end

                    TextBox["Frame"] = Outline
                    TextBox["Box"] = Box
                end


                -- Functions
                do
                    function TextBox.Get()
                        return TextBox.Value
                    end

                    function TextBox.Set(String)
                        TextBox.Box.Text = String
                        TextBox.Value = String

                        Callback(String)
                    end
                end


                -- Input & Connections
                do
                    local Box = TextBox["Box"]

                    Connections[#Connections + 1] = Box.Focused:Connect(function()
                        TextBox.OldValue = Box.Text
                    end)

                    Connections[#Connections + 1] = Box.FocusLost:Connect(function(Submitted)
                        Box.TextColor3 = Theme["Text Color"].A

                        if RequireSubmit and not Submitted then
                            Box.Text = ClearText and Default or TextBox.OldValue

                            return
                        end

                        local String = Box.Text

                        if ClearText then
                            Box.TextColor3 = Theme.Accent
                            Box.Text = ResetText

                            Delay(0.35, function()
                                Box.TextColor3 = Theme["Text Color"].A
                                Box.Text = Default
                            end)
                        end

                        TextBox.Value = ClearText and ResetText or String

                        Callback(String)
                    end)
                end

                SetMetaTable(TextBox, Elements)


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = TextBox
                        else
                            Flags[Category] = {
                                [Flag] = TextBox
                            }
                        end
                    else
                        Flags[Flag] = TextBox
                    end
                end


                Section.Offset += 34

                return TextBox
            end

            function Sections:Label(Parameters)
                Parameters = Parameters or {}

                local Section = self

                local Text = Parameters.Text or "New Label"
                local Unsafe = Parameters.Unsafe or false
                local Flag = Parameters.Flag
                local Category = Parameters.Category


                local Label = {
                    Colorpickers = {},

                    Section = Section,
                    Offset = Section.Offset
                }


                -- Renders
                do
                    local Frame = Menu.Draw("Frame", { Parent = Section.Frame, Position = NewUDim2(0, 0, 0, Section.Offset), Size = NewUDim2(1, 0, 0, 13), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local TextLabel = Menu.Draw("TextLabel", { Parent = Frame, Position = NewUDim2(0, 10, 0, 6), Text = Text, LineHeight = 1.35, TextXAlignment = "Left", TextColor3 = Unsafe and Theme.Unsafe or Theme["Text Color"].A })

                    TextLabel.Size = NewUDim2(1, -38, 0, TextLabel.TextBounds.Y)

                    Label["Frame"] = Frame
                    Label["TextLabel"] = TextLabel
                end


                -- Functions
                do
                    local TextLabel = Label["TextLabel"]

                    function Label.Set() end
                    function Label.Get() end

                    function Label.SetText(String)
                        TextLabel.Text = String
                        TextLabel.Size = NewUDim2(1, -38, 0, TextLabel.TextBounds.Y)
                    end
                end


                SetMetaTable(Label, Elements)


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = Label
                        else
                            Flags[Category] = {
                                [Flag] = Label
                            }
                        end
                    else
                        Flags[Flag] = Label
                    end
                end


                Section.Offset += (Label.TextLabel.TextBounds.Y + 13)

                return Label
            end
        end


        -- Elements Functions
        do
            function Elements:Colorpicker(Parameters)
                Parameters = Parameters or {}

                local Element = self
                local Section = Element.Section
                local Window = Section.Window

                local Name = Parameters.Name or "Text Color"
                local Color = Parameters.Color or Theme.White
                local Transparency = Parameters.Transparency
                local Callback = Parameters.Callback or EmptyFunction
                local Flag = Parameters.Flag
                local Category = Parameters.Category

                local MovingValsat = false
                local MovingHue = false
                local MovingTransparency = false

                local H, S, V = ToHSV(Color)

                local IsTransparency = typeof(Transparency) == "number"


                local Colorpicker = {
                    Color = Color,

                    Hue = H,
                    Sat = S,
                    Vib = V,

                    Transparency = Transparency or 0,
                    Mode = "Solid"
                }


                -- Renders
                do
                    local Outline = Menu.Draw("Frame", { Parent = Element.Frame, Position = NewUDim2(1, -34 - (27 * #Element.Colorpickers), 0, 0), Size = NewUDim2(0, 24, 0, 15), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0 })

                    local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0 })

                    local Image = Menu.Draw("ImageLabel", { Parent = Inline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Color, BorderSizePixel = 0, BackgroundTransparency = Colorpicker.Transparency, Image = Images["Gradient 7"], ImageTransparency = 0.3 })

                    local Button = Menu.Draw("TextButton", { Parent = Outline, Position = EmptyUDim2, Size = NewUDim2(1, 0, 1, 0), BorderSizePixel = 0, BackgroundTransparency = 1, Text = "" })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 3) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 3) })
                    Menu.Draw("UICorner", { Parent = Image, CornerRadius = NewUDim(0, 3) })

                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Inline] = { { "BackgroundColor3", "Contrast", "A" } }
                    end

                    Colorpicker["Frame"] = Outline
                    Colorpicker["Inline"] = Inline

                    Colorpicker["Image"] = Image
                    Colorpicker["Button"] = Button
                end


                -- Functions
                do
                    function Colorpicker.Get()
                        return { Colorpicker.Hue, Colorpicker.Sat, Colorpicker.Vib, Colorpicker.Transparency, Colorpicker.IsRainbow }
                    end

                    function Colorpicker.Set(Value, DoCallback)
                        if DoCallback == nil then
                            DoCallback = true
                        end

                        Colorpicker.Hue, Colorpicker.Sat, Colorpicker.Vib, Colorpicker.Transparency, Colorpicker.IsRainbow = Unpack(Value)

                        Colorpicker.Refresh(DoCallback)
                    end

                    function Colorpicker.FromRGB(Value, DoCallback)
                        local H, S, V = ToHSV(Value)

                        Colorpicker.Set({ H, S, V, Colorpicker.Transparency, Colorpicker.IsRainbow }, DoCallback)
                    end

                    function Colorpicker.Refresh(DoCallback)
                        local Frame = Colorpicker["Image"]

                        local Hue = Colorpicker.Hue

                        local NewColor = FromHSV(Hue, Colorpicker.Sat, Colorpicker.Vib)
                        local NewTransparency = Colorpicker.Transparency

                        Colorpicker.Color = NewColor

                        Frame.BackgroundColor3 = NewColor

                        if Colorpicker.IsOpen then
                            local ValsatFrame = Colorpicker["ValsatFrame"]
                            local ValsatCursor = Colorpicker["ValsatCursor2"]

                            local Solid = Colorpicker["Solid"]
                            local Pulse = Colorpicker["Pulse"]
                            local Rainbow = Colorpicker["Rainbow"]

                            local Mode = Colorpicker.Mode

                            local R, G, B = NewColor.R, NewColor.G, NewColor.B

                            ValsatFrame.ImageColor3 = FromHSV(Hue, 1, 1)

                            ValsatCursor.BackgroundColor3 = NewColor

                            if IsTransparency then
                                local TransparencyFrame = Colorpicker["TransparencyFrame"]

                                Frame.BackgroundTransparency = NewTransparency
                                TransparencyFrame.BackgroundColor3 = NewColor

                                Colorpicker["Alpha Text"].Text = Format("A:%s", Round(NewTransparency * 255))
                            end

                            Colorpicker["Hex Text"].Text = Upper(Format("#%s", ToHex(NewColor)))

                            Colorpicker["Red Text"].Text = Format("R:%s", Round(R * 255))
                            Colorpicker["Green Text"].Text = Format("G:%s", Round(G * 255))
                            Colorpicker["Blue Text"].Text = Format("B:%s", Round(B * 255))

                            Solid.TextColor3 = Mode == "Solid" and Colorpicker.Color or Theme["Text Color"].A
                            Pulse.TextColor3 = Mode == "Pulse" and Colorpicker.Color or Theme["Text Color"].A
                            Rainbow.TextColor3 = Mode == "Rainbow" and Colorpicker.Color or Theme["Text Color"].A
                        end

                        if DoCallback then
                            Callback(NewColor, NewTransparency)
                        end
                    end

                    function Colorpicker.Update()
                        if MovingValsat then
                            local ValsatFrame = Colorpicker["ValsatFrame"]
                            local ValsatCursor = Colorpicker["ValsatCursor"]

                            local MinX = ValsatFrame.AbsolutePosition.X
                            local MaxX = MinX + ValsatFrame.AbsoluteSize.X

                            local MinY = ValsatFrame.AbsolutePosition.Y
                            local MaxY = MinY + ValsatFrame.AbsoluteSize.Y

                            local MouseX = Clamp(Mouse.X, MinX, MaxX)
                            local MouseY = Clamp(Mouse.Y, MinY, MaxY)

                            local Sat = (MouseX - MinX) / (MaxX - MinX)
                            local Vib = 1 - ((MouseY - MinY) / (MaxY - MinY))

                            local VibPos = 1 - Colorpicker.Vib

                            Colorpicker.Sat = Sat
                            Colorpicker.Vib = Vib

                            Menu.Tween(ValsatCursor, NewTweenInfo(0.05, Enum.EasingStyle.Linear), { Position = NewUDim2(Sat, -4, VibPos, -4) })
                        end


                        if MovingHue then
                            local HueFrame = Colorpicker["HueFrame"]
                            local HueCursor = Colorpicker["HueCursor"]

                            local MinY = HueFrame.AbsolutePosition.Y
                            local MaxY = MinY + HueFrame.AbsoluteSize.Y

                            local MouseY = Clamp(Mouse.Y, MinY, MaxY)

                            local Hue = ((MouseY - MinY) / (MaxY - MinY))

                            Colorpicker.Hue = Hue

                            Menu.Tween(HueCursor, NewTweenInfo(0.05, Enum.EasingStyle.Linear), { Position = NewUDim2(0, 1, Hue, 1) })
                        end


                        if MovingTransparency then
                            local TransparencyFrame = Colorpicker["TransparencyFrame"]
                            local TransparencyCursor = Colorpicker["TransparencyCursor"]

                            local MinY = TransparencyFrame.AbsolutePosition.Y
                            local MaxY = MinY + TransparencyFrame.AbsoluteSize.Y

                            local MouseY = Clamp(Mouse.Y, MinY, MaxY)

                            local Trans = ((MouseY - MinY) / (MaxY - MinY))

                            Colorpicker.Transparency = Trans

                            Menu.Tween(TransparencyCursor, NewTweenInfo(0.05, Enum.EasingStyle.Linear), { Position = NewUDim2(0, 1, Trans, 1) })
                        end


                        if MovingValsat or MovingHue or MovingTransparency then
                            Colorpicker.Refresh(true)
                        end


                        RenderStepped:Wait()
                    end

                    function Colorpicker.Open()
                        if Colorpicker.IsOpen then
                            Colorpicker.Close()
                            return
                        end

                        Window:CloseContent({ Window.CurrentColorpicker })


                        Colorpicker.IsOpen = true
                        Window.CurrentColorpicker = Colorpicker


                        -- Renders
                        do
                            local NewColor = Colorpicker.Color
                            local R, G, B = NewColor.R, NewColor.G, NewColor.B

                            local Hex = ToHex(NewColor)


                            -- Main Frame
                            do
