                                local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BorderSizePixel = 0, BackgroundColor3 = Theme.Contrast.A, BackgroundTransparency = 1, ZIndex = Outline.ZIndex + 1 })

                                Menu.Draw("TextLabel", { Parent = Inline, Text = Name, Position = NewUDim2(0, 11, 0, 16), TextXAlignment = "Left", BackgroundTransparency = 1, ZIndex = Inline.ZIndex + 1, TextTransparency = 1, TextColor3 = Theme["Text Color"].A })

                                Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 10) })
                                Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 10) })

