                                local ModeInline = Menu.Draw("Frame", { Parent = ModeOutline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BorderSizePixel = 0, BackgroundColor3 = Theme.Contrast.A, BackgroundTransparency = 1, ZIndex = ModeOutline.ZIndex + 1 })

