                            local CursorOutline = Menu.Draw("Frame", { Parent = ValsatInline, Position = NewUDim2(S, -4, Vib, -4), Size = NewUDim2(0, 10, 0, 10), BackgroundTransparency = 1, BackgroundColor3 = Theme.Black, BorderSizePixel = 0, ZIndex = 56000 })

                            local CursorInline = Menu.Draw("Frame", { Parent = CursorOutline, Position = NewUDim2(0, 2, 0, 2), Size = NewUDim2(1, -4, 1, -4), BackgroundTransparency = 1, BackgroundColor3 = Color, BorderSizePixel = 0, ZIndex = CursorOutline.ZIndex + 1 })

                            Menu.Draw("UICorner", { Parent = CursorOutline, CornerRadius = NewUDim(1, 0) })
                            Menu.Draw("UICorner", { Parent = CursorInline, CornerRadius = NewUDim(1, 0) })

                            -- Colors
                            do
                                Library.Colors[ValsatOutline] = { { "BackgroundColor3", "Inline" } }
                            end

                            Colorpicker["ValsatFrame"] = ValsatInline
                            Colorpicker["ValsatCursor"] = CursorOutline
                            Colorpicker["ValsatCursor2"] = CursorInline
                        end


                        -- Hue
                        do
                            local HueOutline = Menu.Draw("Frame", { Parent = Colorpicker.PickerInline, Position = NewUDim2(0, 188, 0, 63), Size = NewUDim2(0, 18, 0, 175), BorderSizePixel = 0, BackgroundColor3 = Theme.Inline, BackgroundTransparency = 1, ZIndex = Colorpicker.PickerInline.ZIndex + 1 })

                            local HueInline = Menu.Draw("ImageButton", { Parent = HueOutline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BorderSizePixel = 0, BackgroundColor3 = Theme.White, Image = Images["Colorpicker Hue2"], BackgroundTransparency = 1, ImageTransparency = 1, Rotation = 0, ScaleType = "Crop", ZIndex = HueOutline.ZIndex + 1, ClipsDescendants = true })

                            local Cursor = Menu.Draw("Frame", { Parent = HueInline, Position = NewUDim2(0, 0, H, 1), Size = NewUDim2(1, -2, 0, 2), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = HueInline.ZIndex + 1 })

                            Menu.Draw("UIStroke", { Parent = Cursor, Color = Theme.Black, Transparency = 1 })

                            -- Colors
                            do
                                Library.Colors[HueOutline] = { { "BackgroundColor3", "Inline" } }
                            end

                            Colorpicker["HueFrame"] = HueInline
                            Colorpicker["HueCursor"] = Cursor
                        end


                        -- Transparency
                        do
                            if IsTransparency then
                                local TransparencyOutline = Menu.Draw("Frame", { Parent = Colorpicker.PickerInline, Position = NewUDim2(0, 208, 0, 63), Size = NewUDim2(0, 18, 0, 175), BorderSizePixel = 0, BackgroundColor3 = Theme.Inline, BackgroundTransparency = 1, ZIndex = Colorpicker.PickerInline.ZIndex + 1 })

                                local TransparencyInline = Menu.Draw("Frame", { Parent = TransparencyOutline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BorderSizePixel = 0, BackgroundColor3 = Color, ZIndex = TransparencyOutline.ZIndex + 1, ClipsDescendants = true })

                                local Button = Menu.Draw("TextButton", { Parent = TransparencyOutline, Position = EmptyUDim2, Size = NewUDim2(1, 0, 1, 0), BorderSizePixel = 0, BackgroundTransparency = 1, ZIndex = TransparencyOutline.ZIndex + 1, Text = "" })

                                local Cursor = Menu.Draw("Frame", { Parent = TransparencyInline, Position = NewUDim2(0, 1, Transparency, 1), Size = NewUDim2(1, -2, 0, 2), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = TransparencyInline.ZIndex + 1 })

                                Menu.Draw("UIStroke", { Parent = Cursor, Color = Theme.Black, Transparency = 1 })
                                Menu.Draw("UIGradient", { Parent = TransparencyInline, Transparency = NewNumberSequence({ NewNumberKeypoint(0, 0, 0), NewNumberKeypoint(1, 0.95, 0) }), Rotation = 90 })

                                -- Colors
                                do
                                    Library.Colors[TransparencyOutline] = { { "BackgroundColor3", "Inline" } }
                                end

                                Colorpicker["TransparencyFrame"] = TransparencyInline
                                Colorpicker["TransparencyButton"] = Button

                                Colorpicker["TransparencyCursor"] = Cursor
                            end
                        end


                        -- Input & Connections
                        do
                            local ValsatFrame = Colorpicker["ValsatFrame"]
                            local HueFrame = Colorpicker["HueFrame"]
                            local TransparencyFrame = Colorpicker["TransparencyButton"]

                            local Solid = Colorpicker["Solid"]
                            local Pulse = Colorpicker["Pulse"]
                            local Rainbow = Colorpicker["Rainbow"]

                            Library.InputChanged[#Library.InputChanged + 1] = function(Input)
                                if Input.UserInputType == Enum.UserInputType.MouseMovement then
                                    Colorpicker.Update()
                                end
                            end

                            Connections[#Connections + 1] = ValsatFrame.MouseButton1Down:Connect(function()
                                MovingValsat = true

                                Colorpicker.Update()
                            end)

                            Connections[#Connections + 1] = ValsatFrame.InputEnded:Connect(function()
                                if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return end

                                MovingValsat = false
                            end)

                            Connections[#Connections + 1] = HueFrame.MouseButton1Down:Connect(function()
                                MovingHue = true

                                Colorpicker.Update()
                            end)

                            Connections[#Connections + 1] = HueFrame.InputEnded:Connect(function()
                                if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return end

                                MovingHue = false
                            end)

                            Connections[#Connections + 1] = Solid.MouseButton1Down:Connect(function()
                                Colorpicker.Mode = "Solid"

                                Colorpicker.Refresh(true)
                            end)

                            Connections[#Connections + 1] = Pulse.MouseButton1Down:Connect(function()
                                Colorpicker.Mode = "Pulse"

                                Colorpicker.Refresh(true)
                            end)

                            Connections[#Connections + 1] = Rainbow.MouseButton1Down:Connect(function()
                                Colorpicker.Mode = "Rainbow"

                                Colorpicker.Refresh(true)
                            end)

                            if IsTransparency then
                                Connections[#Connections + 1] = TransparencyFrame.MouseButton1Down:Connect(function()
                                    MovingTransparency = true

                                    Colorpicker.Update()
                                end)

                                Connections[#Connections + 1] = TransparencyFrame.InputEnded:Connect(function()
                                    if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return end

                                    MovingTransparency = false
                                end)
                            end
                        end


                        -- Animations
                        do
                            local Descendants = Menu.GetDescendants(Colorpicker.PickerOutline)


                            -- Valsat
                            do
                                local Sat = Colorpicker.Sat
                                local Vib = 1 - Colorpicker.Vib

                                Menu.Tween(Colorpicker.ValsatFrame, NewTweenInfo(0.3, Enum.EasingStyle.Linear), { ImageColor3 = FromHSV(Colorpicker.Hue, 1, 1) })

                                Menu.Tween(Colorpicker.ValsatCursor, NewTweenInfo(0.3, Enum.EasingStyle.Linear), { Position = NewUDim2(Sat, -4, Vib, -4) })

                                Menu.Tween(Colorpicker["ValsatCursor2"], NewTweenInfo(0.3, Enum.EasingStyle.Linear), { BackgroundColor3 = Colorpicker.Color })
                            end


                            -- Hue
                            do
                                if not Colorpicker.IsRainbow then
                                    Menu.Tween(Colorpicker.HueCursor, NewTweenInfo(0.3, Enum.EasingStyle.Linear), { Position = NewUDim2(0, 1, Colorpicker.Hue, 1) })
                                end
                            end


                            -- Transparency
                            do
                                if IsTransparency then
                                    Menu.Tween(Colorpicker.TransparencyFrame, NewTweenInfo(0.3, Enum.EasingStyle.Linear), { BackgroundColor3 = Colorpicker.Color })

                                    Menu.Tween(Colorpicker.TransparencyCursor, NewTweenInfo(0.3, Enum.EasingStyle.Linear), { Position = NewUDim2(0, 1, Colorpicker.Transparency, 1) })
                                end
                            end


                            for i = 1, #Descendants  do
                                local Descendant = Descendants[i]

                                if
                                    IsA(Descendant, "UIGradient") or
                                    IsA(Descendant, "UICorner") or
                                    Descendant == Colorpicker["TransparencyCursor"] or
                                    Descendant == Colorpicker["HueCursor"] or
                                    Descendant == Colorpicker["TransparencyButton"]
                                then
                                    continue
                                end

                                local Properties = { BackgroundTransparency = 0 }

                                if IsA(Descendant, "ImageLabel") or IsA(Descendant, "ImageButton") then
                                    Properties = { ImageTransparency = (IsTransparency and (Descendant == Colorpicker.TransparencyGradient and 0.2)) or 0 }
                                elseif IsA(Descendant, "UIStroke") then
                                    Properties = { Transparency = 0 }
                                elseif IsA(Descendant, "TextLabel") or IsA(Descendant, "TextButton") then
                                    Properties = { TextTransparency = 0 }
                                elseif Descendant == Colorpicker["ValsatCursor2"] then
                                    Properties = { BackgroundTransparency = 0.2 }
                                elseif Descendant == Colorpicker["ValsatCursor"] then
                                    Properties = { BackgroundTransparency = 0.15 }
                                end

                                Menu.Tween(Descendant, NewTweenInfo(0.1, Enum.EasingStyle.Linear), Properties)
                            end
                        end
                    end

                    function Colorpicker.Close()
                        if not Colorpicker.IsOpen then return end

                        Colorpicker.IsOpen = false
                        Window.CurrentColorpicker = nil

                        MovingValsat = false
                        MovingTransparency = false
                        MovingHue = false


                        -- Animations
                        do
                            local Descendants =  Menu.GetDescendants(Colorpicker.PickerOutline)


                            -- Valsat
                            do
                                local Vib = 1 - V

                                Colorpicker.ValsatFrame.BackgroundTransparency = 1

                                Menu.Tween(Colorpicker.ValsatFrame, NewTweenInfo(0.1, Enum.EasingStyle.Linear), { ImageColor3 = FromHSV(H, 1, 1) })

                                Menu.Tween(Colorpicker.ValsatCursor, NewTweenInfo(0.1, Enum.EasingStyle.Linear), { Position = NewUDim2(S, -4, Vib, -4) })
                            end


                            -- Hue
                            do
                                if not Colorpicker.IsRainbow then
                                    Menu.Tween(Colorpicker.HueCursor, NewTweenInfo(0.1, Enum.EasingStyle.Linear), { Position = NewUDim2(0, 1, H, 1) })
                                end
                            end


                            -- Transparency
                            do
                                if IsTransparency then
                                    Menu.Tween(Colorpicker.TransparencyFrame, NewTweenInfo(0.3, Enum.EasingStyle.Linear), { BackgroundColor3 = Color })

                                    Menu.Tween(Colorpicker.TransparencyCursor, NewTweenInfo(0.3, Enum.EasingStyle.Linear), { Position = NewUDim2(0, 1, Transparency, 1) })
                                end
                            end


                            for i = 1, #Descendants do
                                local Descendant = Descendants[i]

                                if
                                    IsA(Descendant, "UIGradient") or
                                    IsA(Descendant, "UICorner")
                                then
                                    continue
                                end

                                local Properties = { BackgroundTransparency = 1 }

                                if IsA(Descendant, "ImageLabel") or IsA(Descendant, "ImageButton") then
                                    Properties = { ImageTransparency = 1 }
                                elseif IsA(Descendant, "UIStroke") then
                                    Properties = { Transparency = 1 }
                                elseif IsA(Descendant, "TextLabel") or IsA(Descendant, "TextButton")then
                                    Properties = { TextTransparency = 1 }
                                end

                                Menu.Tween(Descendant, NewTweenInfo(0.1, Enum.EasingStyle.Linear), Properties)
                            end
                        end


                        Delay(0.1, function()
                            Menu.Remove(Colorpicker.PickerOutline)
                        end)
                    end
                end


                -- Input & Connections
                do
                    Connections[#Connections + 1] = Colorpicker["Button"].MouseButton1Down:Connect(Colorpicker.Open)

                    Library.RenderStepped[#Library.RenderStepped + 1] = function()
                        local Mode = Colorpicker.Mode

                        if Mode == "Solid" then return end

                        if Mode == "Pulse" and IsTransparency then
                            local TransparencyCursor = Colorpicker.TransparencyCursor

                            local NewTransparency = (Sin(Tick() * 1.4) + 1) / 2

                            Colorpicker.Transparency = NewTransparency

                            if TransparencyCursor then
                                TransparencyCursor.Position = NewUDim2(0, 1, NewTransparency, 1)
                            end
                        elseif Mode == "Rainbow" then
                            local HueCursor = Colorpicker.HueCursor

                            local NewHue = (Sin(Tick() * 1.4) + 1) / 2

                            Colorpicker.Hue = NewHue

                            if HueCursor then
                                HueCursor.Position = NewUDim2(0, 1, NewHue, 1)
                            end
                        end

                        Colorpicker.Refresh(true)
                    end
                end


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = Colorpicker
                        else
                            Flags[Category] = {
                                [Flag] = Colorpicker
                            }
                        end
                    else
                        Flags[Flag] = Colorpicker
                    end
                end


                Element.Colorpickers[#Element.Colorpickers + 1] = Colorpicker

                return Element, Colorpicker
            end

            function Elements:Keybind(Parameters)
                -- TODO: Keybinds options on RMB

                Parameters = Parameters or {}

                local Element = self
                local Section = Element.Section
                local Window = Section.Window

                local Default = Parameters.Default or "None"
                local Mode = Parameters.Mode or "Toggle"
                local Modes = Parameters.Modes or { "Always", "Toggle", "On Hold", "Off Hold" }
                local Activated = Parameters.Activated or EmptyFunction
                local Changed = Parameters.Changed or EmptyFunction
                local Flag = Parameters.Flag
                local Category = Parameters.Category


                local Keybind = {
                    Modes = Modes,
                    Mode = Mode,

                    Active = Mode == "Always" or Mode == "Off Hold",
                    IsOpen = false,

                    Value = {},
                    ModeButtons = {},
                    Update = {},

                    Name = Parameters.Name or Flag or "Keybind",
                    Exclude = Parameters.Exclude and true or false
                }


                -- Renders
                do
                    local Outline = Menu.Draw("Frame", { Parent = Element.Frame, Position = NewUDim2(1, -154, 0, 0), Size = NewUDim2(0, 144, 0, 26), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0 })

                    local Inline = Menu.Draw("Frame", { Parent = Outline, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0 })

                    local Button = Menu.Draw("TextButton", { Parent = Outline, Position = EmptyUDim2, Size = NewUDim2(1, 0, 1, 0), Text = "", BackgroundTransparency = 1 })

                    local Label = Menu.Draw("TextLabel", { Parent = Inline, AnchorPoint = NewVector2(0.5, 0.5), Position = NewUDim2(0.5, 0, 0.5, -1), Text = "Key: None", BackgroundTransparency = 1, TextColor3 = Theme["Text Color"].B })

                    Menu.Draw("UICorner", { Parent = Outline, CornerRadius = NewUDim(0, 6) })
                    Menu.Draw("UICorner", { Parent = Inline, CornerRadius = NewUDim(0, 6) })

                    -- Colors
                    do
                        Library.Colors[Outline] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Outline] = { { "BackgroundColor3", "Contrast", "A" } }
                    end

                    Keybind["Frame"] = Outline

                    Keybind["Label"] = Label
                    Keybind["Button"] = Button
                end


                -- Functions
                do
                    function Keybind.Get()
                        return { Keybind.Active, Keybind.Value }
                    end

                    function Keybind.Set(Table)
                        local Value = Table[2]

                        Keybind.Active = Table[1]
                        Keybind.Value = Value

                        Keybind.Label.Text = Format("Key: %s", #Value > 0 and Keybind.Shorten(Value[2]) or "None")

                        Changed(Value, Keybind.Active)
                    end

                    function Keybind.Shorten(String)
                        for Index, Value in next, Menu.InputShorts do
                            String = Gsub(String, Index, Value)
                        end

                        return String
                    end

                    function Keybind.SetKeyFromInput(Input)
                        if Input.EnumType and (Input.EnumType == Enum.KeyCode or Input.EnumType == Enum.UserInputType) then
                            local InputName = Input.Name

                            if Find(Menu.KeyCodes, InputName) or Find(Menu.InputTypes, InputName) then
                                local Value = { Input.EnumType == Enum.KeyCode and "KeyCode" or "UserInputType", InputName }

                                Keybind.Value = Value
                                Keybind.Label.Text = Format("Key: %s", #Value > 0 and Keybind.Shorten(Value[2]) or "None")

                                if Keybind.SelectConnection then
                                    Keybind.SelectConnection:Disconnect()
                                    Keybind.SelectConnection = nil
                                end

                                Changed(Keybind.Value, Keybind.Active)

                                return true
                            elseif InputName == "Backspace" or InputName == "Escape" then
                                Keybind.Value = {}
                                Keybind.Label.Text = "Key: None"

                                if Keybind.SelectConnection then
                                    Keybind.SelectConnection:Disconnect()
                                    Keybind.SelectConnection = nil
                                end

                                Element.Set(false)
                                Keybind.Active = false

                                Changed(Keybind.Value, Keybind.Active)

                                return true
                            end
                        end

                        return false
                    end

                    function Keybind.SetPickable(Boolean)
                        Keybind.IsSelecting = Boolean

                        Keybind.Label.TextColor3 = Boolean and Theme["Text Color"].A or Theme["Text Color"].B

                        if Boolean then
                            Keybind.Close()

                            Delay(0.1, function()
                                Keybind.SelectConnection = UserInputService.InputBegan:Connect(function(Input)
                                    local Selected = Keybind.SetKeyFromInput(Input.KeyCode.Name ~= "Unknown" and Input.KeyCode or Input.UserInputType)

                                    if Selected then
                                        Keybind.SetPickable(false)
                                    end
                                end)

                                Connections[#Connections + 1] = Keybind.SelectConnection
                            end)
                        else
                            if Keybind.SelectConnection then
                                Keybind.SelectConnection:Disconnect()
                                Keybind.SelectConnection = nil
                            end
                        end
                    end
                end


                -- Input & Connections
                do
                    local KeybindButton = Keybind["Button"]

                    Connections[#Connections + 1] = KeybindButton.MouseButton1Down:Connect(function()
                        Keybind.SetPickable(not Keybind.IsSelecting)
                    end)

                    Library.InputBegan[#Library.InputBegan + 1] = function(Input)
                        if UserInputService:GetFocusedTextBox() then return end

                        local Value = Keybind.Value

                        if not Keybind.IsSelecting and Value[1] and Value[2] then
                            if Input.KeyCode == Enum[Value[1]][Value[2]] or Input.UserInputType == Enum[Value[1]][Value[2]] then
                                if Keybind.Mode == "Always" then return end

                                local NewActive = true

                                if Keybind.Mode == "Toggle" then
                                    NewActive = not Element.Value
                                elseif Keybind.Mode == "Off Hold" then
                                    NewActive = false
                                end

                                Keybind.Active = NewActive
                                Element.Set(NewActive)

                                if NewActive then
                                    Activated()
                                end
                            end
                        end
                    end

                    Library.InputEnded[#Library.InputEnded + 1] = function(Input)
                        if UserInputService:GetFocusedTextBox() then return end

                        local Value = Keybind.Value

                        if not Keybind.IsSelecting and Value[1] and Value[2] then
                            if Input.KeyCode == Enum[Value[1]][Value[2]] or Input.UserInputType == Enum[Value[1]][Value[2]] then
                                if Keybind.Mode == "Toggle" or Keybind.Mode == "Always" then return end

                                local NewActive = false

                                if Keybind.Mode == "Off Hold" then
                                    NewActive = true
                                end

                                Keybind.Active = NewActive
                                Element.Set(NewActive)

                                if NewActive then
                                    Activated()
                                end
                            end
                        end
                    end
                end


                if Flag then
                    if Category then
                        if typeof(Flags[Category]) == "table" then
                            Flags[Category][Flag] = Keybind
                        else
                            Flags[Category] = {
                                [Flag] = Keybind
                            }
                        end
                    else
                        Flags[Flag] = Keybind
                    end
                end


                Keybind.SetKeyFromInput(Default)
                Element.Set(Mode == "Always" or Mode == "Off Hold")

                Element.Bind = Keybind

                Window.Keybinds[#Window.Keybinds + 1] = Keybind

                Section.Offset += 9

                return Keybind
            end

            function Elements:Settings(Parameters)
                Parameters = Parameters or {}

                local Element = self
                local Section = Element.Section
                local Window = Section.Window

                local SectionFrame = Section.Frame

                local Size = Parameters.Size or 54


                local Settings = {
                    IsOpen = false,

                    Offset = 13,
                    Window = Section.Window
                }


                -- Renders
                do
                    local AbsolutePosition = SectionFrame.AbsolutePosition

                    local Outline = Menu.Draw("Frame", { Parent = Element.Frame, Position = NewUDim2(1, -12, 0, 0), Size = NewUDim2(0, 14, 0, 14), BackgroundTransparency = 1, BorderSizePixel = 0 })

                    local Image = Menu.Draw("ImageButton", { Parent = Outline, Position = NewUDim2(0, -14, 0, -2), Size = NewUDim2(1, 0, 1, 0), BackgroundTransparency = 1, Image = Images["Settings 2"], ImageColor3 = NewRGB(128, 128, 128) })

                    local Outer = Menu.Draw("Frame", { Parent = Menu.Overlay2, Position = NewUDim2(0, AbsolutePosition.X + 10, 0, AbsolutePosition.Y + Element.Offset + 20), Size = NewUDim2(0, SectionFrame.AbsoluteSize.X - 20, 0, Size), BackgroundColor3 = Theme.Outline, BorderSizePixel = 0, Visible = false })

                    local Inner = Menu.Draw("Frame", { Parent = Outer, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Inline, BorderSizePixel = 0, ZIndex = Outer.ZIndex + 1 })

                    local Background = Menu.Draw("Frame", { Parent = Inner, Position = NewUDim2(0, 1, 0, 1), Size = NewUDim2(1, -2, 1, -2), BackgroundColor3 = Theme.Contrast.A, BorderSizePixel = 0, ZIndex = Inner.ZIndex + 1 })

                    Menu.Draw("UICorner", { Parent = Outer, CornerRadius = NewUDim(0, 10) })
                    Menu.Draw("UICorner", { Parent = Inner, CornerRadius = NewUDim(0, 10) })
                    Menu.Draw("UICorner", { Parent = Background, CornerRadius = NewUDim(0, 10) })

                    -- Colors
                    do
                        Library.Colors[Outer] = { { "BackgroundColor3", "Outline" } }
                        Library.Colors[Inner] = { { "BackgroundColor3", "Inline" } }
                        Library.Colors[Background] = { { "BackgroundColor3", "Contrast", "A" } }
                    end

                    Settings["Frame"] = Outer

                    Settings["Image"] = Image
                end


                -- Functions
                do
                    local Frame = Settings["Frame"]
                    local Image = Settings["Image"]

                    function Settings.Open()
                        if Settings.IsOpen then
                            Settings.Close()
                            return
                        end

                        Settings.IsOpen = true
                        Window.CurrentSection = Settings

                        Menu.Tween(Image, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageColor3 = Theme.Accent })

                        Library.Colors[Image] = { { "BackgroundColor3", "Accent" } }

                        Frame.Visible = true
                    end

                    function Settings.Close()
                        if not Settings.IsOpen then return end

                        Settings.IsOpen = false
                        Window.CurrentSection = nil


                        Menu.Tween(Image, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageColor3 = NewRGB(128, 128, 128) })

                        Library.Colors[Image] = nil

                        Frame.Visible = false
                    end
                end


                -- Input & Connections
                do
                    local Image = Settings["Image"]
                    local Frame = Settings["Frame"]

                    Connections[#Connections + 1] = Image.MouseButton1Down:Connect(Settings.Open)

                    Connections[#Connections + 1] = Image.MouseEnter:Connect(function()
                        if not Settings.IsOpen then
                            Menu.Tween(Image, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageColor3 = Theme["Text Color"].A })
                        end
                    end)

                    Connections[#Connections + 1] = Image.MouseLeave:Connect(function()
                        if not Settings.IsOpen then
                            Menu.Tween(Image, NewTweenInfo(0.15, Enum.EasingStyle.Linear), { ImageColor3 = NewRGB(128, 128, 128) })
                        end
                    end)

                    Connections[#Connections + 1] = SectionFrame:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
                        local AbsolutePosition = SectionFrame.AbsolutePosition

                        Frame.Position = NewUDim2(0, AbsolutePosition.X + 10, 0, AbsolutePosition.Y + Element.Offset + 20)
                    end)
                end


                SetMetaTable(Settings, Sections)


                return Settings
            end
        end


        -- Input & Connections
        do
            Connections[#Connections + 1] = UserInputService.InputBegan:Connect(function(Input)
                local Began = Library.InputBegan

                for i = 1, #Began do
                    Began[i](Input)
                end
            end)

            Connections[#Connections + 1] = UserInputService.InputEnded:Connect(function(Input)
                local Ended = Library.InputEnded

                for i = 1, #Ended do
                    Ended[i](Input)
                end
            end)

            Connections[#Connections + 1] = UserInputService.InputChanged:Connect(function(Input)
                local Changed = Library.InputChanged

                for i = 1, #Changed do
                    Changed[i](Input)
                end
            end)

            Connections[#Connections + 1] = RenderStepped:Connect(function(DeltaTime)
                local Render = Library.RenderStepped

                for i = 1, #Render do
                    Render[i](DeltaTime)
                end
            end)

            Connections[#Connections + 1] = PlayerAdded:Connect(function(Player)
                local Added = Library.PlayerAdded

                for i = 1, #Added do
                    Added[i](Player)
                end
            end)

            Connections[#Connections + 1] = PlayerRemoving:Connect(function(Player)
                local Removing = Library.PlayerRemoving

                for i = 1, #Removing do
                    Removing[i](Player)
                end
            end)
        end

        Library.Images = Images
        Menu.Library = Library
        return Library;
    end
end


-- Example
do
    local Library = Menu.Library
    local Images = Menu.Images
    local Theme = Menu.Theme

    local Tab

    local Category
    local SubCategory

    local Group
    local SubGroup

    local Section

    local Settings


    local Window = Library:Window()
    do
        Tab = Window:Tab({
            Name = "Rage",
            Icon = Images.Rage,
            IconSize = NewUDim2(0, 23, 0, 20),
            IconPosition = NewUDim2(0.5, 0, 0.5, -8),
            Opened = true
        })
        d
            Category = Tab:Category()
            do
                SubCategory = Category[1]
                do
                    Group = SubCategory:Group()
                    do
                        SubGroup = Group[1]
                        do
                            Section = SubGroup:Section()
                            do
                                Section:Dropdown({
                                    Name = "Current Config"
                                })

                                Section:Toggle()
                            end

                            Section = SubGroup:Section({
                                Size = 230,
                                Name = "General"
                            })
                            do
                                Section:Toggle({
                                    Name = "Enable"
                                })

                                Section:Label({
                                    Text = "Aim Key"
                                }):Keybind()

                                Section:Dropdown({
                                    Name = "Disable If...",
                                    Options = { "In Air", "Smoke", "Flashed" },
                                    Min = 0
                                })

                                Section:Toggle({
                                    Name = "Visualize FOV"
                                }):Colorpicker({
                                    Color = NewRGB(230, 35, 35),
                                    Name = "Color 1"
                                }):Colorpicker({
                                    Color = NewRGB(230, 35, 35),
                                    Name = "Color 2",
                                    Transparency = 0
                                })

                                Settings = Section:Dropdown({
                                    Name = "Recoil Control",
                                    Default = "On Aim",
                                    Options = { "On Aim", "On Shoot" }
                                }):Settings()
                                do
                                    Settings:Slider({
                                        Name = "Extra Delay",
                                        Min = 0, Max = 10, Default = 6,
                                        Prefix = "s"
                                    })
                                end
                            end

                            Section = SubGroup:Section({
                                Side = "Right",
                                Name = "Targeting",
                                Size = 176
                            })
                            do
                                Section:Dropdown({
                                    Name = "Hitbox",
                                    Options = { "Head" },
                                    Default = { "Head" }
                                })

                                Settings = Section:Slider({
                                    Name = "FOV",
                                    Min = 0, Max = 15, Default = 4,
                                    Decimals = 0.01
                                }):Settings()
                                do
                                    Settings:Slider({
                                        Name = "Extra Delay",
                                        Min = 0, Max = 10, Default = 6,
                                        Prefix = "s"
                                    })
                                end

                                Section:Slider({
                                    Name = "Min. Visiblity Time",
                                    Min = 0, Max = 10, Default = 0,
                                    Prefix = "ms"
                                })
                            end

                            Section = SubGroup:Section({
                                Side = "Right",
                                Name = "Humanization",
                                Size = 192
                            })
                            do
                                Section:Toggle({
                                    Name = "Randomization",
                                    Default = true
                                })

                                Section:Slider({
                                    Name = "Speed (Pitch)",
                                    Min = 0, Max = 15, Default = 30,
                                    Prefix = "%"
                                })

                                Section:Slider({
                                    Name = "Speed (Yaw)",
                                    Min = 0, Max = 15, Default = 30,
                                    Prefix = "%"
                                })

                                Section:Slider({
                                    Name = "Limit Aim Time",
                                    Min = 0, Max = 10, Default = 0,
                                    Prefix = "s",
                                    Specials = {"Off", 0}
                                })
                            end
                        end
                    end
                end
            end
        end

        Tab = Window:Tab({
            Name = "Legit",
            Icon = Images.Legit,
            IconSize = NewUDim2(0, 20, 0, 20),
            IconPosition = NewUDim2(0.5, 0, 0.5, -9)
        })
        do
        end

        Tab = Window:Tab({
            Name = "Visuals",
            Icon = Images.Visuals,
            IconSize = NewUDim2(0, 21, 0, 20),
            IconPosition = NewUDim2(0.5, 0, 0.5, -8)
        })
        do
        end

        Tab = Window:Tab({
            Name = "Misc",
            Icon = Images["Misc 2"],
            IconSize = NewUDim2(0, 21, 0, 20),
            IconPosition = NewUDim2(0.5, 0, 0.5, -8)
        })
        do
        end

        Tab = Window:Tab({
            Name = "Style",
            Icon = Images.Skins,
            IconSize = NewUDim2(0, 20, 0, 20),
            IconPosition = NewUDim2(0.5, 0, 0.5, -8)
        })
        do
            Category = Tab:Category({
                Categories = {
                    { "Main", "Main styles" }
                }
            })
            do
                SubCategory = Category[1]
                do
                    Section = SubCategory:Section({
                        Name = "Primary",
                        Fill = true
                    })
                    do
                        Section:Label({
                            Text = "Outline Color"
                        }):Colorpicker({
                            Name = "Outline Color",
                            Color = Theme.Outline,
                            Callback = function(Color)
                                Menu.Theme.Outline = Color

                                Library:SetTheme(nil, { "Outline" })
                            end
                        })

                        Section:Label({
                            Text = "Inline Color"
                        }):Colorpicker({
                            Name = "Inline Color",
                            Color = Theme.Inline,
                            Callback = function(Color)
                                Menu.Theme.Inline = Color

                                Library:SetTheme(nil, { "Inline" })
                            end
                        })

                        Section:Label({
                            Text = "Contrast A"
                        }):Colorpicker({
                            Name = "Contrast A",
                            Color = Theme.Contrast.A,
                            Callback = function(Color)
                                Menu.Theme.Contrast.A = Color

                                Library:SetTheme(nil, { "Contrast" }, { "A" })
                            end
                        })

                        Section:Label({
                            Text = "Contrast B"
                        }):Colorpicker({
                            Name = "Contrast B",
                            Color = Theme.Contrast.B,
                            Callback = function(Color)
                                Menu.Theme.Contrast.B = Color

                                Library:SetTheme(nil, { "Contrast", "B" })
                            end
                        })
                    end

                    Section = SubCategory:Section({
                        Name = "Secondary",
                        Side = "Right",
                        Fill = true
                    })
                    do
                        Section:Label({
                            Text = "Divider Color"
                        }):Colorpicker({
                            Name = "Divider Color",
                            Color = Theme.Divider,
                            Callback = function(Color)
                                Menu.Theme.Divider = Color

                                Library:SetTheme(nil, { "Divider" })
                            end
                        })

                        Section:Label({
                            Text = "Accent Color"
                        }):Colorpicker({
                            Name = "Accent Color",
                            Color = Theme.Accent,
                            Callback = function(Color)
                                Menu.Theme.Accent = Color

                                Library:SetTheme(nil, { "Accent" })
                            end
                        })
                    end
                end
            end
        end

        Tab = Window:Tab({
            Name = "Scripts",
            Icon = Images.Scripts,
            IconSize = NewUDim2(0, 26, 0, 21),
            IconPosition = NewUDim2(0.5, 0, 0.5, -8)
        })
        do
        end
    end
end
